#!/bin/bash
# continue_v5b.sh (2026-11-13 02:00, generated by v5b/mk_v5b.py from v5/continue_v5.sh): v5 content, style_weights
# signature fixed (v5 check failed 01:32), motion = paper v2 retarget (380 s) ALONE (coordinator correction 01:57: no Pico), data/motion_v5b.
# continue_v5b.sh (2026-11-13 00:55). v5b = ONE combined restart from v4j (coordinator 00:30, user decisions in docs/USER_RULES.md):
#  v4k content unchanged (slow fwd/yaw caps, turn_effort, turn_drift -2.0, no backward, extended_v4k with prop routes)
#  motion: the paper's own reference retargeted to X2 (data/motion_v5b, copied from data/motions/hiking_release_x2)
#  j: discriminator input weighted by body part (legs, pelvis, waist 1.0; shoulders, elbows 0.3; wrists, head out); the paper's
#     single discriminator; restarted fresh (input 330 -> 550), policy and value from the checkpoint
#  simcheck: simulator faults end as time-outs (simfault.py), sim_fault share in the heartbeat (supervise_x2_v5.py)
# Gate: waits for $S/GO_v5b (touched after the user's approval of the retarget review) and the retarget file, then for the next
# 125-iteration checkpoint (GO_v5b containing "now": the newest checkpoint at once). CPU pre-flight precheck_v5.py before v4j stops.
# Trial: 75 iterations, marks over the last 30 (iterations 46-75). The 32-iteration trial of v4k was censored: no episode can time
# out before about 42 iterations after a full reset, so "episode length" counted falls only; v4j restarted from the same
# checkpoint (00:18) scored ep 195 and turn 0.17 in its first 32 iterations, below v4k (184, 0.21), and 520-780 / 0.67 by 7044.
T=/mnt/filesystem-g4/tracks/hiking; X=$T/code/x2_port; D=$X/files_instinctlab/tasks/parkour/config/x2
NAME=x2_parkour_v4; RUN=$T/runs/$NAME; S=$RUN/_supervisor
M=$T/data/motion_v5b; SRC=$M/parkour_motion_without_run_x2_v2_retargetted.npz
TR=$T/_trash/$(date +%F); mkdir -p $TR
note() { echo "$(date '+%F %T') $*" >> $TR/NOTES.txt; }
echo "$(date +%T) v5b armed: waiting for $S/GO_v5b and $SRC" >> $S/launch.txt
until [ -f $S/GO_v5b ] && [ -f $SRC ]; do sleep 30; done
newest() { ls $RUN/*/model_*.pt 2>/dev/null | sed 's/.*model_\([0-9]*\)\.pt/\1/' | sort -n | tail -1; }
if grep -q now $S/GO_v5b; then WAIT_FOR=$(newest); else WAIT_FOR=$(( ($(newest) / 125 + 1) * 125 )); fi
echo "$(date +%T) v5b GO seen; restart from model_$WAIT_FOR" >> $S/launch.txt
until ls $RUN/*/model_${WAIT_FOR}.pt >/dev/null 2>&1; do sleep 20; done
sleep 30
if ! $HOME/hiking-env/bin/python $X/v5b/precheck_v5b.py $X/v5b/continue_v5b.sh $D > $S/precheck_v5b.log 2>&1; then
  echo "$(date +%T) v5b NOT started: CPU pre-flight failed ($(grep -a FAIL $S/precheck_v5b.log | head -3 | tr '\n' ' ')); v4j keeps training, not stopped" >> $S/launch.txt
  exit 1
fi
echo "$(date +%T) v5b CPU pre-flight passed ($(grep -a '^motion\|^discriminator' $S/precheck_v5b.log | tr '\n' ' '))" >> $S/launch.txt
L0=$(grep -a "Curriculum/terrain_levels" $S/train.log | tail -20 | awk '{s+=$NF;n++} END{print s/n}')
E0=$(grep -a "Mean episode length" $S/train.log | tail -20 | awk '{s+=$NF;n++} END{print s/n}')
W0=$(grep -a "turn/rate_along_cmd" $S/train.log | tail -20 | awk '{s+=$NF;n++} END{print s/n}')
T0=$(date +%s)
touch $S/STOP
while tmux has -t hiking_x2 2>/dev/null; do sleep 3; done
[ -f $S/STOP ] && { DST=$TR/STOP_${NAME}_$(date +%H%M%S); mv $S/STOP $DST; note "$DST: stop flag of $NAME, used by continue_v5b.sh"; }
pkill -f crashguard_v4.sh && echo "$(date -u '+%F %T') crashguard of v4j stopped by continue_v5b.sh" >> $S/gates.txt
cp $S/terrain_levels.pt $S/terrain_levels_prestop.pt
H=$(date +%H%M%S); BK=$TR/v4j_files_v5_$H; mkdir -p $BK
for f in extended.py routes.py keep.py contact.py staged.py fixed.py; do cp $D/$f $BK/$f; done
note "$BK: extended, routes, keep, contact, staged, fixed of v4j (to $WAIT_FOR), replaced by the .v4k/.v5 files"
cat > $X/fallback_v4j.sh <<EOF
#!/bin/bash
# restore v4j's files and resume v4j (written by continue_v5b.sh at $H)
for f in extended.py routes.py keep.py contact.py staged.py fixed.py; do cp $BK/\$f $D/\$f; done
rm -f $D/slow.py
bash $X/apply.sh > /dev/null
rm -f $T/code/hiking-in-the-wild/InstinctLab/source/instinctlab/instinctlab/tasks/parkour/config/x2/slow.py
cp $S/terrain_levels_prestop.pt $S/terrain_levels.pt
bash $X/start_x2_parkour_v4j.sh
EOF
for f in extended.py routes.py keep.py contact.py slow.py; do cp $D/$f.v4k $D/$f; done
for f in staged.py fixed.py; do cp $D/$f.v5 $D/$f; done
ls -l $SRC >> $S/gates.txt
bash $X/apply.sh > /dev/null
VENV="HIKING_X2_OPTS=a,c,d,f,r,s,t,k,y,o,z,w,g,v,j HIKING_X2_VX_BACK=0 HIKING_X2_SLOW_FWD_SHARE=0.25 HIKING_X2_SLOW_TURN_SHARE=0.4 HIKING_X2_SLOW_VX=0.1 HIKING_X2_TURN_DRIFT_WEIGHT=-2.0 HIKING_X2_SIDESTEP_SHARE=0.3 HIKING_X2_SIDESTEP_V=0.3 HIKING_X2_ROUTE_VY=0.2 HIKING_EXTENDED_TERRAINS=$T/data/extended_v4k HIKING_X2_MOTION_DIR=$T/data/motion_v5b HIKING_X2_MOTION_YAML=parkour_motion_without_run_x2_v2.yaml"
CK=$RUN/_check_v5b_$(date +%H%M%S); mkdir -p $CK
( cd $T/code/hiking-in-the-wild/InstinctLab && env $VENV HIKING_X2_ROUTE_SHARE=0.7 HIKING_X2_STAGE=500,1500 HIKING_X2_VX_MIN=0.45 \
  HIKING_X2_TURN_SHARE=0.15 HIKING_X2_STAND_SHARE=0.10 HIKING_X2_STOP_ANY_YAW=1 OMNI_KIT_ACCEPT_EULA=YES PYTHONUNBUFFERED=1 \
  timeout 1800 $HOME/hiking-env/bin/python $X/check_x2_env.py --headless --task Instinct-Parkour-ExtendedFixed-Amp-X2-v0 \
  --num_envs 256 --steps 150 --out $CK ) > $CK/check.log 2>&1
CKRC=$?
echo "$(date +%T) v5b construction check exit $CKRC (log $CK/check.log)" >> $S/launch.txt
NR=$(grep -ao "\[X2 routes\] [0-9]* routes" $CK/check.log | head -1 | awk '{print $3}')
echo "$(date +%T) route table in the v5b check: ${NR:-none} routes; $(grep -a '\[X2 simfault\]' $CK/check.log | head -1 | cut -c1-200)" >> $S/launch.txt
if [ $CKRC != 0 ] || grep -aq "Traceback" $CK/check.log || [ "${NR:-0}" -lt 100 ] || ! grep -aq "wall_contact_graded" $CK/check.log || ! grep -aq "turn_effort" $CK/check.log || ! grep -aq "sim_fault" $CK/check.log; then
  bash $X/fallback_v4j.sh
  echo "$(date +%T) v5b NOT started: construction check failed (exit $CKRC, routes ${NR:-none}, or wall_contact_graded / turn_effort / sim_fault missing); v4j resumed; last error: $(grep -aE '^[A-Za-z]*(Error|Exception)' $CK/check.log | tail -1 | cut -c1-200)" >> $S/launch.txt
  tmux new -d -s guard4j "FB_STAGED=$D/staged.py FB_START=$X/start_x2_parkour_v4j.sh bash $X/crashguard_v4.sh $L0 $E0"
  exit 1
fi
ENVV="HIKING_X2_OPTS=a,c,d,f,r,s,t,k,y,o,z,w,g,v,j HIKING_X2_VX_BACK=0 HIKING_X2_SLOW_FWD_SHARE=0.25 HIKING_X2_SLOW_TURN_SHARE=0.4 HIKING_X2_SLOW_VX=0.1 HIKING_X2_TURN_DRIFT_WEIGHT=-2.0 HIKING_X2_STAGE=500,1500 HIKING_X2_CAM_RAND=1 HIKING_X2_ALIVE_EARLY=0.3 HIKING_X2_WAIT_EARLY=2 HIKING_X2_STYLE_EARLY=0.3 HIKING_X2_FALL_PENALTY=8 HIKING_X2_REF_START=0.5 HIKING_X2_AIR_TD_WEIGHT=140 HIKING_X2_VX_MIN=0.45 HIKING_X2_TURN_SHARE=0.15 HIKING_X2_LEVELS_OUT=$S/terrain_levels.pt HIKING_X2_LEVELS_IN=$S/terrain_levels.pt HIKING_X2_STAND_SHARE=0.10 HIKING_X2_OVERSPEED_WEIGHT=-3.0 HIKING_X2_STOP_WEIGHT=-2.0 HIKING_X2_STOP_ANY_YAW=1 HIKING_X2_ROUTE_SHARE=0.7 HIKING_X2_SIDESTEP_SHARE=0.3 HIKING_X2_SIDESTEP_V=0.3 HIKING_X2_ROUTE_VY=0.2 HIKING_EXTENDED_TERRAINS=$T/data/extended_v4k HIKING_X2_MOTION_DIR=$T/data/motion_v5b HIKING_X2_MOTION_YAML=parkour_motion_without_run_x2_v2.yaml"
printf '#!/bin/bash\n# Resume %s with the options of its continuation from %s (continue_v5b.sh: v4k + paper motion on X2, weighted style input, simcheck).\ntmux new -d -s hiking_x2 "%s %s %s/v5/supervise_x2_v5.py --task Instinct-Parkour-ExtendedFixed-Amp-X2-v0 --name %s --total 30000 --num_envs 8192 --save_interval 125 2>&1 | tee -a %s/runs/%s_supervisor_tmux.log"\n' \
  $NAME $WAIT_FOR "$ENVV" '$HOME/hiking-env/bin/python' $X $NAME $T $NAME > $X/start_x2_parkour_v5b.sh
LOG0=$(stat -c %s $S/train.log 2>/dev/null || echo 0)
SUP0=$(grep -c ' start pid [0-9]* from iteration' $S/supervisor.log 2>/dev/null); SUP0=${SUP0:-0}
echo "continue from newest checkpoint (v5b): $ENVV started $(date '+%Y-%m-%d %H:%M:%S')" >> $S/launch.txt
bash $X/start_x2_parkour_v5b.sh
OK=0; WHY="fewer than 3 new iterations within 10 minutes"
for i in $(seq 1 60); do
  sleep 10
  NEW=$(tail -c +$((LOG0 + 1)) $S/train.log 2>/dev/null)
  if printf '%s' "$NEW" | grep -aq "Traceback"; then WHY="Traceback in train.log"; break; fi
  if [ $(printf '%s' "$NEW" | grep -ac "Learning iteration") -ge 3 ]; then OK=1; break; fi
  N=$(grep -c ' start pid [0-9]* from iteration' $S/supervisor.log 2>/dev/null); if [ "${N:-0}" -ge $((SUP0 + 2)) ]; then WHY="trainer restarted by its supervisor"; break; fi
  if ! tmux has -t hiking_x2 2>/dev/null; then WHY="supervisor exited"; break; fi
done
if [ $OK = 1 ]; then
  for i in $(seq 1 200); do
    NEW=$(tail -c +$((LOG0 + 1)) $S/train.log 2>/dev/null)
    if printf '%s' "$NEW" | grep -aq "Traceback"; then OK=0; WHY="Traceback in train.log during the trial"; break; fi
    [ $(printf '%s' "$NEW" | grep -ac "Learning iteration") -ge 76 ] && break
    sleep 20
  done
  if [ $OK = 1 ]; then
    NEW=$(tail -c +$((LOG0 + 1)) $S/train.log)
    L1=$(printf '%s' "$NEW" | grep -a "Curriculum/terrain_levels" | tail -30 | awk '{s+=$NF;n++} END{print (n?s/n:0)}')
    E1=$(printf '%s' "$NEW" | grep -a "Mean episode length" | tail -30 | awk '{s+=$NF;n++} END{print (n?s/n:0)}')
    N1=$(printf '%s' "$NEW" | grep -ac "Learning iteration")
    W1=$(printf '%s' "$NEW" | grep -a "turn/rate_along_cmd" | tail -30 | awk '{s+=$NF;n++} END{print (n?s/n:0)}')
    DR=$(printf '%s' "$NEW" | grep -a "discriminator shapes changed\|fresh discriminator" | head -1 | cut -c1-120)
    echo "$(date +%T) v5b trial after $N1 iterations (marks over the last 30): level $L1 (before $L0), episode $E1 (before $E0), turn rate $W1 (before $W0); $DR" >> $S/launch.txt
    if ! python3 -c "import sys; sys.exit(0 if $N1 >= 75 and $L1 >= 0.8 * $L0 and $E1 >= 0.4 * $E0 and $W1 >= 0.5 * $W0 else 1)"; then
      OK=0; WHY="trial failed: level $L1 vs $L0, episode $E1 vs $E0, turn $W1 vs $W0 over the last 30 of $N1 iterations"
    fi
  fi
fi
if [ $OK = 1 ]; then
  R=$(tail -c +$((LOG0 + 1)) $S/train.log | grep -a "level_keeper\]\|X2 v5\|X2 simfault" | head -3 | tr '\n' ' ' | cut -c1-300)
  echo "$(date +%T) continuation v5b is training, GPU idle about $(( $(date +%s) - T0 )) s; $R" >> $S/launch.txt
  tmux new -d -s guard5 "FB_STAGED=$D/staged.py FB_START=$X/fallback_v4j.sh bash $X/crashguard_v4.sh $L0 $E0"
else
  touch $S/STOP
  while tmux has -t hiking_x2 2>/dev/null; do sleep 3; done
  [ -f $S/STOP ] && { DST=$TR/STOP_${NAME}_$(date +%H%M%S); mv $S/STOP $DST; note "$DST: stop flag of the failed v5b continuation"; }
  bash $X/fallback_v4j.sh
  echo "$(date +%T) continuation v5b FAILED ($WHY; see train.log after byte $LOG0); v4j resumed (fallback_v4j.sh)" >> $S/launch.txt
  tmux new -d -s guard4j "FB_STAGED=$D/staged.py FB_START=$X/start_x2_parkour_v4j.sh bash $X/crashguard_v4.sh $L0 $E0"
fi
